/* .list 바로 아래 li 만 */
.list > li { color: blue; }

/* h2 바로 다음 p 하나 */
h2 + p { font-weight: bold; }

/* h2 뒤의 모든 형제 p */
h2 ~ p { color: gray; }

.card {
  box-sizing: border-box;
  width: 200px;      /* 테두리까지 200px */
  padding: 20px;
  border: 5px solid; /* content 는 150px */
}
.wrap { width: 600px; margin: 0 auto; } /* 가로 가운데 */

.a { margin-bottom: 30px; }
.b { margin-top: 20px; }   /* .a 와 .b 사이 간격은 30px */

.list { display: flex; flex-direction: column; }
.list .item { margin: 20px 0; } /* 아이템 사이 간격은 40px */

.container {
  display: flex;
  justify-content: space-between; /* 가로: 양 끝 + 사이 균등 */
  align-items: center;            /* 세로: 가운데 */
  gap: 8px;
}
.container .grow { flex: 1; }

.board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.board .banner { grid-column: 1 / 4; } /* 첫 줄 전체 */

.card { position: relative; }
.card .badge {
  position: absolute;  /* .card 기준 */
  top: 8px;
  right: 8px;
}
.header { position: sticky; top: 0; }

.cards { display: grid; grid-template-columns: 1fr; }

@media (min-width: 600px) {
  .cards { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 1000px) {
  .cards { grid-template-columns: repeat(4, 1fr); }
}

