const scores = [70, 95, 82];
const passed = scores.filter((s) => s >= 80); // [95, 82]
const plus = scores.map((s) => s + 5);        // [75, 100, 87]
console.log(scores);                           // [70, 95, 82] (그대로)

const [first, ...others] = scores;
console.log(first, others); // 70 [95, 82]

console.log(double(4)); // 8 (선언문은 위에서도 호출 가능)
function double(n) { return n * 2; }

const sum = (...nums) => nums.reduce((a, b) => a + b, 0);
console.log(sum(1, 2, 3)); // 6

const counter = {
  count: 0,
  start() {
    setTimeout(function () {
      console.log(this.count); // undefined (this = window)
    });
    setTimeout(() => {
      console.log(this.count); // 0 (바깥 start 의 this = counter)
    });
  },
};
counter.start();

const list = document.querySelector("#list");
const li = document.createElement("li");
li.textContent = "새 항목";
list.prepend(li);          // 맨 앞에

li.classList.toggle("done"); // true (붙음)

const form = document.querySelector("form");
form.addEventListener("submit", (event) => {
  event.preventDefault(); // 새로고침 막기
  console.log("직접 처리");
});

// 이벤트 위임
list.addEventListener("click", (e) => {
  if (e.target.matches("li")) e.target.remove();
});

const params = new URLSearchParams(location.search);
console.log(params.get("page")); // "2"

let n = 0;
const id = setInterval(() => {
  n++;
  console.log(n);          // 1, 2, 3
